void write_smoke_report_file(const filesystem::path& path, const string& title) {
    filesystem::create_directories(path.parent_path());
    ofstream ofs(path);
    if (!ofs) {
        throw runtime_error("failed to write smoke report: " + path.string());
    }
    ofs << title << '\n';
}


