void run_policy_gate_nightly_smoke_case(const TestOptions&) {
    const filesystem::path artifactRoot = source_package_root() / "artifacts";
    const PolicyGateManifest manifest = build_policy_gate_manifest(artifactRoot, "phase22_nightly_smoke");
    require_test(policy_gate_manifest_satisfied(manifest), "policy gate nightly smoke expected satisfied manifest");
    require_test(
        require_policy_gate_family(manifest, "split_tie_organic_symmetric").status == PolicyGateStatus::PASS,
        "policy gate nightly smoke expected split_tie_organic_symmetric PASS"
    );
    require_test(
        require_policy_gate_family(manifest, "automorphism_probe_large").status == PolicyGateStatus::PASS,
        "policy gate nightly smoke expected automorphism_probe_large PASS"
    );
    require_test(
        require_policy_gate_family(manifest, "planner_tie_mixed_organic").status == PolicyGateStatus::NON_APPLICABLE,
        "policy gate nightly smoke expected planner_tie_mixed_organic NON_APPLICABLE"
    );
    const PolicyGateFamilyResult& compareReady =
        require_policy_gate_family(manifest, "planner_tie_mixed_organic_compare_ready");
    require_test(
        compareReady.status == PolicyGateStatus::DIAGNOSTIC_ONLY,
        "policy gate nightly smoke expected compare_ready diagnostic-only status"
    );
    require_test(
        !compareReady.countsAsProductionEvidence,
        "policy gate nightly smoke expected compare_ready to stay out of production evidence"
    );
}

void run_policy_gate_non_applicable_smoke_case(const TestOptions&) {
    FamilyApplicabilitySummary applicability;
    applicability.family = "planner_tie_mixed_organic";
    applicability.generatedStateCount = 48U;
    applicability.compareEligibleStateCount = 0U;
    applicability.compareIneligibleStateCount = 48U;
    applicability.compareIneligibleReasonHistogram["no_split_ready"] = 48U;
    applicability.dominantIneligibleReason = "no_split_ready";
    applicability.dominantIneligibleReasonConfidence = 1.0;
    applicability.classification = FamilyApplicabilityClassification::NON_APPLICABLE;
    const PolicyGateFamilyResult result =
        evaluate_planner_tie_non_applicable_gate(applicability, PolicyGateCompareEvidence{});
    require_test(
        result.status == PolicyGateStatus::NON_APPLICABLE,
        "policy gate non-applicable smoke expected NON_APPLICABLE"
    );
    require_test(!result.driftFlag, "policy gate non-applicable smoke expected no drift");
}

void run_planner_tie_organic_applicability_drift_smoke_case(const TestOptions&) {
    FamilyApplicabilitySummary applicability;
    applicability.family = "planner_tie_mixed_organic";
    applicability.generatedStateCount = 48U;
    applicability.splitReadyStateCount = 3U;
    applicability.tieReadyStateCount = 2U;
    applicability.compareEligibleStateCount = 2U;
    applicability.compareIneligibleStateCount = 46U;
    applicability.compareIneligibleReasonHistogram["no_split_ready"] = 46U;
    applicability.compareRelevance = 2.0 / 48.0;
    applicability.splitReadyRelevance = 3.0 / 48.0;
    applicability.dominantIneligibleReason = "no_split_ready";
    applicability.dominantIneligibleReasonConfidence = 46.0 / 46.0;
    const PolicyGateFamilyResult result =
        evaluate_planner_tie_non_applicable_gate(applicability, PolicyGateCompareEvidence{});
    require_test(
        result.status == PolicyGateStatus::INSUFFICIENT_EVIDENCE,
        "planner tie applicability drift smoke expected INSUFFICIENT_EVIDENCE"
    );
    require_test(result.driftFlag, "planner tie applicability drift smoke expected drift flag");
}

